#!/usr/bin/env python3
"""Carbon-aware compute scheduling solver (PySCIPOpt)."""
import csv
import json
import os
import sys

from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
SUB_DIR = "/app/submissions"
SOLUTION_PATH = os.path.join(SUB_DIR, "solution.csv")
TOL = 1e-5


def read_data():
    with open(os.path.join(DATA_DIR, "config.json")) as f:
        config = json.load(f)

    slots = []
    slot_index = {}
    with open(os.path.join(DATA_DIR, "time_slots.csv")) as f:
        for row in csv.DictReader(f):
            sid = row["slot_id"]
            slot_index[sid] = int(row["hour_index"])
            slots.append(sid)
    slots.sort(key=lambda s: slot_index[s])

    regions = {}
    region_order = []
    with open(os.path.join(DATA_DIR, "regions.csv")) as f:
        for row in csv.DictReader(f):
            rid = row["region_id"]
            regions[rid] = {
                "name": row["region_name"],
                "grid_zone": row["grid_zone"],
                "base_latency_ms": float(row["base_latency_ms"]),
                "residency": row["data_residency"],
                "opex": float(row["opex_multiplier"]),
            }
            region_order.append(rid)

    cap = {}
    with open(os.path.join(DATA_DIR, "region_slot_capacity.csv")) as f:
        for row in csv.DictReader(f):
            cap[(row["region_id"], row["slot_id"])] = float(
                row["compute_capacity_kw"]
            ) - float(row["maintenance_reserved_kw"])

    env = {}
    with open(os.path.join(DATA_DIR, "region_slot_environment.csv")) as f:
        for row in csv.DictReader(f):
            env[(row["region_id"], row["slot_id"])] = {
                "carbon": float(row["carbon_kg_per_kwh"]),
                "price": float(row["energy_price_per_kwh"]),
                "green": float(row["green_score"]),
            }

    workloads = {}
    workload_order = []
    with open(os.path.join(DATA_DIR, "workloads.csv")) as f:
        for row in csv.DictReader(f):
            wid = row["workload_id"]
            workloads[wid] = {
                "class": row["workload_class"],
                "duration": int(row["duration_slots"]),
                "power": float(row["power_kw"]),
                "earliest": row["earliest_slot"],
                "deadline": row["deadline_slot"],
                "priority": float(row["priority_weight"]),
                "residency": row["data_residency"],
                "max_latency": float(row["max_latency_ms"]),
                "flex": int(row["flexible_for_green_shift"]),
            }
            workload_order.append(wid)

    elig = {}
    with open(os.path.join(DATA_DIR, "workload_region_eligibility.csv")) as f:
        for row in csv.DictReader(f):
            wid = row["workload_id"]
            rid = row["region_id"]
            elig.setdefault(wid, {})[rid] = {
                "latency": float(row["latency_ms"]),
                "transfer": float(row["data_transfer_cost"]),
            }

    return config, slots, slot_index, regions, region_order, cap, env, workloads, workload_order, elig


def residency_ok(w_res, r_res):
    if w_res == r_res:
        return True
    # NA workloads may run in US regions; US workloads only in US regions.
    if w_res == "NA" and r_res == "US":
        return True
    return False


def build_candidate_options(workloads, workload_order, elig, regions, slot_index, env):
    """Return dict options[w] = list of (r, t, coeff, green_term) for eligible starts."""
    options = {}
    for w in workload_order:
        wd = workloads[w]
        dur = wd["duration"]
        e_i = slot_index[wd["earliest"]]
        d_i = slot_index[wd["deadline"]]
        opts = []
        for r, info in sorted(elig.get(w, {}).items()):
            if r not in regions:
                continue
            if not residency_ok(wd["residency"], regions[r]["residency"]):
                continue
            if info["latency"] > wd["max_latency"] + TOL:
                continue
            opex = regions[r]["opex"]
            lat_cost = 0.021 * wd["priority"] * info["latency"]
            trans_cost = info["transfer"]
            for t in range(e_i, d_i - dur + 2):
                if t < 0 or t + dur - 1 > 23:
                    continue
                energy = 0.0
                carbon = 0.0
                green = 0.0
                for s in range(t, t + dur):
                    sid = "h%02d" % s
                    e = env.get((r, sid))
                    if e is None:
                        energy = None
                        break
                    energy += e["price"]
                    carbon += e["carbon"]
                    green += e["green"]
                if energy is None:
                    continue
                coeff = (
                    wd["power"] * opex * energy
                    + 0.092 * wd["power"] * carbon
                    + lat_cost
                    + trans_cost
                    + 0.82 * wd["priority"] * t
                )
                green_term = wd["power"] * dur * (green / dur - 0.53)
                opts.append((r, t, coeff, green_term))
        options[w] = opts
    return options


def greedy_feasible(workloads, workload_order, options, cap, slot_index, env, regions):
    """Greedy fallback: assign workloads in priority order to cheapest feasible option."""
    assignment = {}
    used = {}  # (r, s) -> power used
    for w in sorted(workload_order, key=lambda x: (-workloads[x]["priority"], x)):
        wd = workloads[w]
        best = None
        for (r, t, coeff, _gt) in options.get(w, []):
            ok = True
            for s in range(t, t + wd["duration"]):
                sid = "h%02d" % s
                if used.get((r, s), 0.0) + wd["power"] > cap[(r, sid)] + TOL:
                    ok = False
                    break
            if ok:
                if best is None or coeff < best[2]:
                    best = (r, t, coeff)
        if best is None:
            return None
        assignment[w] = (best[0], best[1])
        for s in range(best[1], best[1] + wd["duration"]):
            sid = "h%02d" % s
            used[(best[0], s)] = used.get((best[0], s), 0.0) + wd["power"]
    return assignment


def validate(assignment, workloads, workload_order, elig, regions, cap, slot_index, env, config):
    errors = []
    seen = set()
    for w in workload_order:
        if w not in assignment:
            errors.append("missing workload %s" % w)
            continue
        if w in seen:
            errors.append("duplicate workload %s" % w)
        seen.add(w)
        r, t = assignment[w]
        wd = workloads[w]
        if r not in elig.get(w, {}):
            errors.append("%s not eligible for %s" % (w, r))
            continue
        if not residency_ok(wd["residency"], regions[r]["residency"]):
            errors.append("%s residency violation in %s" % (w, r))
        if elig[w][r]["latency"] > wd["max_latency"] + TOL:
            errors.append("%s latency violation in %s" % (w, r))
        if t < slot_index[wd["earliest"]] or t + wd["duration"] - 1 > slot_index[wd["deadline"]]:
            errors.append("%s start %d outside window" % (w, t))
    used = {}
    for w, (r, t) in assignment.items():
        wd = workloads[w]
        for s in range(t, t + wd["duration"]):
            sid = "h%02d" % s
            used[(r, s)] = used.get((r, s), 0.0) + wd["power"]
    for (r, s), p in used.items():
        sid = "h%02d" % s
        if p > cap[(r, sid)] + TOL:
            errors.append("capacity violation %s %s: %.3f > %.3f" % (r, sid, p, cap[(r, sid)]))
    gnum = 0.0
    gden = 0.0
    for w, (r, t) in assignment.items():
        wd = workloads[w]
        if wd["flex"] != 1:
            continue
        g = 0.0
        for s in range(t, t + wd["duration"]):
            sid = "h%02d" % s
            g += env[(r, sid)]["green"]
        gnum += wd["power"] * (g / wd["duration"])
        gden += wd["power"]
    if gden > 0:
        share = gnum / gden
        if share < config["flexible_green_energy_min_share"] - TOL:
            errors.append("green share %.6f < %.6f" % (share, config["flexible_green_energy_min_share"]))
    return errors


def compute_objective(assignment, workloads, elig, regions, env, slot_index):
    total = 0.0
    for w, (r, t) in assignment.items():
        wd = workloads[w]
        info = elig[w][r]
        energy = 0.0
        carbon = 0.0
        for s in range(t, t + wd["duration"]):
            sid = "h%02d" % s
            energy += env[(r, sid)]["price"]
            carbon += env[(r, sid)]["carbon"]
        total += (
            wd["power"] * regions[r]["opex"] * energy
            + 0.092 * wd["power"] * carbon
            + 0.021 * wd["priority"] * info["latency"]
            + info["transfer"]
            + 0.82 * wd["priority"] * t
        )
    return total


def write_solution(assignment, workload_order):
    with open(SOLUTION_PATH, "w", newline="") as f:
        wtr = csv.writer(f)
        wtr.writerow(["workload_id", "region_id", "start_slot"])
        for w in workload_order:
            r, t = assignment[w]
            wtr.writerow([w, r, "h%02d" % t])


def main():
    os.makedirs(SUB_DIR, exist_ok=True)
    config, slots, slot_index, regions, region_order, cap, env, workloads, workload_order, elig = read_data()

    options = build_candidate_options(workloads, workload_order, elig, regions, slot_index, env)
    for w in workload_order:
        if not options[w]:
            print("WARNING: no feasible options for %s" % w)

    # Greedy warm start (also serves as fallback).
    greedy = greedy_feasible(workloads, workload_order, options, cap, slot_index, env, regions)
    if greedy is not None:
        gerr = validate(greedy, workloads, workload_order, elig, regions, cap, slot_index, env, config)
        print("Greedy warm start: %d workloads, errors=%d, obj=%.6f" % (len(greedy), len(gerr), compute_objective(greedy, workloads, elig, regions, env, slot_index)))
    else:
        print("Greedy warm start failed.")

    model = Model("carbon_aware_scheduling")
    model.setParam("gaprel", 0.0005)
    time_limit = 300.0
    env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_limit is not None:
        try:
            time_limit = min(time_limit, float(env_limit))
        except ValueError:
            pass
    model.setParam("limits/time", time_limit)

    x = {}
    obj_coeff = {}
    green_coeff = {}
    for w in workload_order:
        for (r, t, coeff, gterm) in options[w]:
            v = model.addVar(name="x_%s_%s_%02d" % (w, r, t), vtype="B", lb=0.0, ub=1.0, obj=0.0)
            x[(w, r, t)] = v
            obj_coeff[(w, r, t)] = coeff
            green_coeff[(w, r, t)] = gterm

    # Assignment constraints
    for w in workload_order:
        terms = [x[(w, r, t)] for (r, t, _c, _g) in options[w]]
        if terms:
            model.addCons(quicksum(terms) == 1, name="assign_%s" % w)

    # Capacity constraints
    cap_cons_terms = {}
    for w in workload_order:
        wd = workloads[w]
        for (r, t, _c, _g) in options[w]:
            for s in range(t, t + wd["duration"]):
                cap_cons_terms.setdefault((r, s), []).append((wd["power"], x[(w, r, t)]))
    for (r, s), terms in cap_cons_terms.items():
        sid = "h%02d" % s
        model.addCons(
            quicksum([(p, v) for (p, v) in terms]) <= cap[(r, sid)],
            name="cap_%s_%s" % (r, sid),
        )

    # Green-shift constraint
    gterms = [(green_coeff[(w, r, t)], x[(w, r, t)]) for (w, r, t) in x if workloads[w]["flex"] == 1]
    if gterms:
        model.addCons(quicksum(gterms) >= 0.0, name="green_shift")

    obj_expr = quicksum([(obj_coeff[k], v) for k, v in x.items()])
    model.setObjective(obj_expr, sense="minimize")

    # Warm start
    if greedy is not None:
        try:
            sol = model.createSol()
            for (w, r, t), v in x.items():
                gr, gt = greedy.get(w, (None, None))
                model.setSolVal(sol, v, 1.0 if (gr == r and gt == t) else 0.0)
            model.addSol(sol)
        except Exception as e:
            print("Warm start failed: %s" % e)

    assignment = None
    status = None
    objval = None
    try:
        model.optimize()
        status = model.getStatus()
        print("SCIP status: %s, nsols: %d" % (status, model.getNSols()))
        if model.getNSols() > 0:
            sol = model.getBestSol()
            objval = model.getObjVal()
            print("Objective: %.8f" % objval)
            assignment = {}
            for w in workload_order:
                best = None
                for (r, t, _c, _g) in options[w]:
                    val = model.getVal(x[(w, r, t)])
                    if val is not None and val > 0.5:
                        best = (r, t)
                        break
                if best is None:
                    # Fallback: pick cheapest option for this workload
                    best = min(options[w], key=lambda o: o[2])[:2]
                assignment[w] = best
    except Exception as e:
        print("Solver error: %s" % e)
        if greedy is not None:
            assignment = greedy
        status = "error"

    if assignment is None or len(assignment) != len(workload_order):
        if greedy is not None:
            assignment = greedy
        else:
            # Last-resort: assign each workload to its cheapest option regardless of capacity
            assignment = {}
            for w in workload_order:
                if options[w]:
                    assignment[w] = min(options[w], key=lambda o: o[2])[:2]
                else:
                    r0 = next(iter(elig.get(w, {})), region_order[0])
                    assignment[w] = (r0, slot_index[workloads[w]["earliest"]])

    errs = validate(assignment, workloads, workload_order, elig, regions, cap, slot_index, env, config)
    obj = compute_objective(assignment, workloads, elig, regions, env, slot_index)
    print("Final assignment objective: %.8f" % obj)
    print("Validation errors: %d" % len(errs))
    for e in errs[:20]:
        print("  -", e)

    write_solution(assignment, workload_order)
    print("Wrote %s with %d rows" % (SOLUTION_PATH, len(workload_order)))

    try:
        model.free()
    except Exception:
        pass


if __name__ == "__main__":
    main()
